<?php require 'app.php';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{bb_check_csrf();bb_schema();$email=trim($_POST['email'] ?? '');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>255) throw new InvalidArgumentException('Enter a valid email.');
if(($_POST['action'] ?? '')==='unsubscribe') {if(!preg_match('/^[a-f0-9]{64}$/D',$_POST['token'] ?? '')) throw new InvalidArgumentException('Use your private unsubscribe code.');bb_query('DELETE FROM newsletter_subscribers WHERE email=? AND unsubscribe_token=?','ss',[$email,$_POST['token']]);$message='The subscription matching those details has been removed.';}
else {if(empty($_POST['consent'])) throw new InvalidArgumentException('Confirm that you want book updates.');$token=bin2hex(random_bytes(32));bb_query('INSERT INTO newsletter_subscribers(email,unsubscribe_token) VALUES (?,?) ON DUPLICATE KEY UPDATE unsubscribe_token=VALUES(unsubscribe_token)','ss',[$email,$token]);$message='You are subscribed. Save this private unsubscribe code: '.$token;}
}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Book updates | BookBang</title><link rel="stylesheet" href="backend.css"></head><body><?php include 'navbar.php'; ?><main class="bb-panel"><h1>Book updates</h1><?php if($message): ?><p class="bb-success" style="overflow-wrap:anywhere"><?= bb_h($message) ?></p><?php endif; ?><?php if($error): ?><p role="alert" class="bb-error"><?= bb_h($error) ?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= bb_h(bb_csrf()) ?>"><label>Email<input type="email" name="email" required></label><label><input type="checkbox" name="consent" required> I want occasional BookBang updates about books and offers.</label><button>Subscribe</button></form><h2>Unsubscribe</h2><form method="post"><input type="hidden" name="csrf" value="<?= bb_h(bb_csrf()) ?>"><input type="hidden" name="action" value="unsubscribe"><label>Email<input type="email" name="email" required></label><label>Private unsubscribe code<input name="token" required></label><button>Unsubscribe</button></form></main></body></html>
